-- Maps the published lexicon enum improvement_status to status_class (open | stalled | closed).
-- D-4a: NULL means stalled only when improvement_status IS NULL AND permit_issue_date IS NOT NULL.
-- Excluded and needs_review permits are never emitted, so a NULL status is an Expired source word.
-- Join with IS NOT DISTINCT FROM so the NULL row matches.
CREATE OR REPLACE VIEW travis_austin_status_map AS
SELECT * FROM (VALUES
  ('Completed', 'closed'),
  ('OnHold', 'open'),
  ('Permitted', 'open'),
  ('Planned', 'open'),
  (NULL, 'stalled')
) AS t(improvement_status, status_class);
